<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { AlertTriangle, Plus, Search } from 'lucide-vue-next'
import Modal from '../components/Modal.vue'
import Pager from '../components/Pager.vue'
import { api, dateLabel, dateTimeLabel, isArchived, issueStatuses, messageOf, notify, pickFields, projectName, query, severities, ui } from '../api'
import type { Issue, Page } from '../types'
const props=defineProps<{revision:number;initialQuery?:string}>();const emit=defineEmits<{changed:[]}>()
const issues=ref<Issue[]>([]),total=ref(0),offset=ref(0),project=ref(''),status=ref(''),search=ref(props.initialQuery||''),error=ref(''),loading=ref(false),open=ref(false),saving=ref(false),formError=ref(''),editing=ref<Issue>();const limit=30
const blank=()=>({project_id:project.value||ui.projects.find(p=>p.status!=='archived')?.id||'',title:'',description:'',severity:'minor',source:'现场发现',owner:'',due_at:'',root_cause:'',solution:'',verify_result:'',rejection_reason:''});const form=reactive(blank())
const readonly=computed(()=>editing.value?.status==='closed'||editing.value?.status==='rejected'||isArchived(editing.value?.project_id||''))
const nextStatus=computed(()=>({open:'analyzing',analyzing:'fixing',fixing:'verifying',verifying:'closed'}[editing.value?.status||'']))
const transitionLabel=computed(()=>({analyzing:'开始分析',fixing:'进入修复',verifying:'提交验证',closed:'验证通过并关闭'}[nextStatus.value||'']||''))
async function load(){loading.value=true;error.value='';try{const page=await api<Page<Issue>>(`/api/issues?${query({project_id:project.value,status:status.value,q:search.value,limit,offset:offset.value})}`);issues.value=page.items;total.value=page.total}catch(e){error.value=messageOf(e)}finally{loading.value=false}}
onMounted(load);watch(()=>props.revision,load);watch([project,status],()=>{offset.value=0;void load()});watch(()=>props.initialQuery,q=>{search.value=q||'';offset.value=0;void load()})
async function edit(issue?:Issue){formError.value='';if(!issue){editing.value=undefined;Object.assign(form,blank());open.value=true;return}try{editing.value=await api<Issue>(`/api/issues/${issue.id}`);Object.assign(form,pickFields(editing.value,blank()));form.due_at=(editing.value.due_at||'').slice(0,10);open.value=true}catch(e){notify(messageOf(e),true)}}
async function save(transition?:string){if(saving.value||readonly.value)return;if(transition==='closed'&&!form.verify_result.trim()){formError.value='填写验证结果后才能关闭问题';return}if(transition==='fixing'&&!form.root_cause.trim()){formError.value='请先填写根因分析';return}if(transition==='verifying'&&!form.solution.trim()){formError.value='请先填写解决方案';return}if(transition==='rejected'&&!form.rejection_reason.trim()){formError.value='请在下方填写驳回原因';return}saving.value=true;formError.value='';try{const path=editing.value?`/api/issues/${editing.value.id}${transition?'/transition':''}`:'/api/issues';const saved=await api<Issue>(path,{method:editing.value&&!transition?'PATCH':'POST',body:JSON.stringify({...pickFields(form,blank()),...(editing.value?{version:editing.value.version}:{}),...(transition?{status:transition}:{})})});notify(transition?`问题已${issueStatuses[transition]}`:editing.value?'问题信息已保存':'问题已登记');if(editing.value){editing.value=await api<Issue>(`/api/issues/${saved.id}`);Object.assign(form,pickFields(editing.value,blank()));form.due_at=(editing.value.due_at||'').slice(0,10)}else open.value=false;emit('changed');await load()}catch(e){formError.value=messageOf(e)}finally{saving.value=false}}
function page(next:number){offset.value=next;void load()}
</script>
<template><div class="page-heading"><div><h1>问题台账</h1><p class="page-description">从发现、分析到验证关闭，每一步都有依据。</p></div><button class="button primary" :disabled="!ui.projects.some(p=>p.status!=='archived')" @click="edit()"><Plus :size="18"/>登记问题</button></div><form class="filter-bar" @submit.prevent="offset=0;load()"><select v-model="project" aria-label="问题所属项目"><option value="">全部项目</option><option v-for="p in ui.projects" :key="p.id" :value="p.id">{{p.name}}</option></select><select v-model="status" aria-label="问题状态"><option value="">全部状态</option><option v-for="(name,key) in issueStatuses" :key="key" :value="key">{{name}}</option></select><div class="input-with-icon"><Search :size="16"/><input v-model="search" placeholder="搜索问题" aria-label="搜索问题"/></div><button type="submit" class="button subtle">查询</button></form><div v-if="error" class="error-banner" role="alert">{{error}}<button class="text-button" @click="load">重试</button></div><div class="surface"><p v-if="loading" class="loading-message">正在读取问题…</p><div v-else-if="!issues.length" class="empty-state"><AlertTriangle :size="36"/><h2>让问题有记录，也有结果</h2><p>{{ui.projects.length?'登记发现的问题，持续跟进到验证通过。':'请先在「项目」中创建所属项目。'}}</p><button v-if="ui.projects.some(p=>p.status!=='archived')" class="button primary" @click="edit()">登记问题</button></div><div v-else class="table-scroll"><table><thead><tr><th>问题 / 项目</th><th>级别</th><th>负责人</th><th>期望解决</th><th>状态</th><th class="right">操作</th></tr></thead><tbody><tr v-for="issue in issues" :key="issue.id"><td><button class="table-title" @click="edit(issue)">{{issue.title}}</button><small>{{issue.code}} <span v-if="!project"> / {{projectName(issue.project_id)}}</span></small></td><td><span class="severity" :class="issue.severity"><i/>{{severities[issue.severity]}}</span></td><td>{{issue.owner||'未指定'}}</td><td>{{dateLabel(issue.due_at)}}</td><td><span class="badge" :class="issue.status">{{issueStatuses[issue.status]}}</span></td><td class="right"><button class="text-button" @click="edit(issue)">查看详情</button></td></tr></tbody></table></div><Pager :offset="offset" :limit="limit" :total="total" @change="page"/></div><Modal :open="open" :title="editing?`${editing.code||'问题'} · ${issueStatuses[editing.status]}`:'登记问题'" wide @close="!saving&&(open=false)"><form class="modal-body" @submit.prevent="save()"><ol v-if="editing&&editing.status!=='rejected'" class="issue-flow" aria-label="问题处理流程"><li v-for="(label,key) in {open:'发现',analyzing:'分析',fixing:'修复',verifying:'验证',closed:'关闭'}" :key="key" :class="{current:editing.status===key}">{{label}}</li></ol><fieldset :disabled="readonly||saving"><label>问题标题 <span class="required">*</span><input v-model="form.title" required maxlength="200" autofocus/></label><div class="form-row"><label>所属项目 <span class="required">*</span><select v-model="form.project_id" required :disabled="!!editing"><option v-for="p in ui.projects.filter(p=>p.status!=='archived'||p.id===form.project_id)" :key="p.id" :value="p.id">{{p.name}}</option></select></label><label>严重程度<select v-model="form.severity"><option v-for="(name,key) in severities" :key="key" :value="key">{{name}}</option></select></label></div><div class="form-row"><label>负责人<input v-model="form.owner" maxlength="100"/></label><label>期望解决日期<input v-model="form.due_at" type="date"/></label></div><label>问题来源<input v-model="form.source" maxlength="100" placeholder="例如：现场巡检、客户反馈"/></label><label>问题描述<textarea v-model="form.description" rows="3" placeholder="具体发生了什么，影响范围是什么"/></label><template v-if="editing"><div class="form-divider">处理记录</div><label>根因分析<textarea v-model="form.root_cause" rows="2" placeholder="分析原因后填写，进入修复前必填"/></label><label>解决方案<textarea v-model="form.solution" rows="2" placeholder="记录采取的措施，提交验证前必填"/></label><label>验证结果<textarea v-model="form.verify_result" rows="2" placeholder="验证方法、结果和证据；关闭问题前必填"/></label><details v-if="['open','analyzing','fixing'].includes(editing.status)" class="rejection-details"><summary>需要驳回此问题？</summary><label>驳回原因<textarea v-model="form.rejection_reason" rows="2"/></label><button type="button" class="button danger small" :disabled="saving||!form.rejection_reason.trim()" @click="save('rejected')">驳回问题</button></details></template></fieldset><div v-if="editing?.history?.length" class="issue-history"><h3>状态记录</h3><p v-for="(entry,index) in editing.history" :key="entry.id||index"><time>{{dateTimeLabel(entry.created_at)}}</time><span>{{entry.operator||'本人'}} {{entry.from_status?issueStatuses[entry.from_status]+' → ':''}}{{issueStatuses[entry.to_status||entry.status||'']||entry.action||'更新'}}</span></p></div><p v-if="formError" class="form-error" role="alert">{{formError}}</p><div class="modal-footer"><span v-if="readonly" class="muted">{{isArchived(form.project_id)?'项目已归档，问题只读':'终态问题只读'}}</span><div v-else class="row-actions"><button type="submit" class="button" :disabled="saving">{{saving?'正在保存…':editing?'保存信息':'登记问题'}}</button><button v-if="editing&&nextStatus" type="button" class="button primary" :disabled="saving" @click="save(nextStatus)">{{transitionLabel}}</button><button v-if="editing?.status==='verifying'" type="button" class="button subtle" :disabled="saving" @click="save('fixing')">验证未通过，退回修复</button></div></div></form></Modal></template>
